// Domain 3 — Layer 2 control and security: flashcards (FortiOS 7.6 / FortiSwitchOS 7.6).
export default [
  { id: 'd3-f001', topic: '3.1', front: 'Where is 802.1X configured for managed FortiSwitch ports?', back: 'On the FortiGate: `config switch-controller security-policy 802-1X`, then per port `set port-security-policy <name>`.' },
  { id: 'd3-f002', topic: '3.1', front: 'Port-based vs MAC-based 802.1X?', back: '`802.1X`: one authentication opens the port. `802.1X-mac-based`: each device authenticates; up to **20** per port.' },
  { id: 'd3-f003', topic: '3.1', front: 'Guest vs auth-fail vs authserver-timeout VLAN?', back: 'Guest: no 802.1X response. Auth-fail: credentials rejected. Authserver-timeout: RADIUS doesn\'t answer (period 3–15 s, default 3).' },
  { id: 'd3-f004', topic: '3.1', front: 'MAB on a FortiSwitch security policy?', back: '`set mac-auth-bypass enable` (default disable): the MAC is used as RADIUS user name and password.' },
  { id: 'd3-f005', topic: '3.1', front: '`802-1X-settings` defaults?', back: '`reauth-period` 60 min, `max-reauth-attempt` 3, `tx-period` 30 s, `link-down-auth set-unauth`, `mab-reauth` disable. Per-switch `local-override`.' },
  { id: 'd3-f006', topic: '3.1', front: 'FortiOS 7.6 `auth-priority` values?', back: '`legacy` (EAP first, default after upgrade), `dot1x-mab`, `mab-dot1x`. MAB only: `auth-order mab`.' },
  { id: 'd3-f007', topic: '3.1', front: 'RADIUS dynamic VLAN by name: matched against?', back: 'Tunnel-Private-Group-Id name ↔ VLAN interface **description**. Ties broken by `assignment-priority` (default 128, lowest wins).' },
  { id: 'd3-f008', topic: '3.1', front: 'Firewall policy needed for FortiSwitch 802.1X?', back: 'Yes: allow RADIUS from the FortiLink interface to the RADIUS server.' },
  { id: 'd3-f009', topic: '3.1', front: '`access-mode` values on a managed switch port?', back: '`static` (default), `dynamic` (dynamic port policy via `port-policy`), `nac` (FortiLink NAC policies).' },
  { id: 'd3-f010', topic: '3.1', front: 'Where does a new device on a NAC port go first?', back: 'The **onboarding VLAN** (`fortilink-settings` → `nac-ports` → `onboarding-vlan`), until a NAC policy matches.' },
  { id: 'd3-f011', topic: '3.1', front: 'Dynamic port policy actions?', back: '`lldp-profile`, `qos-policy`, `802-1x` policy, `vlan-policy`, `bounce-port-link`. Keep a catch-all default rule last.' },
  { id: 'd3-f012', topic: '3.1', front: 'Port `learning-limit` range and default?', back: '1–128; default 0 = no limit. Static MACs don\'t count. Violations logged only with `log-mac-limit-violations enable`.' },
  { id: 'd3-f013', topic: '3.1', front: 'Sticky MAC persistence?', back: '`set sticky-mac enable` survives link down/up; lost at reboot unless `execute switch-controller switch-action sticky-mac save ...`.' },
  { id: 'd3-f014', topic: '3.2', front: 'Enable DHCP snooping in FortiLink mode?', back: 'On the FortiGate VLAN interface: `set switch-controller-dhcp-snooping enable` (off by default).' },
  { id: 'd3-f015', topic: '3.2', front: 'Default DHCP trust of managed switch ports?', back: '**Untrusted**. Trust server-facing ports with `set dhcp-snooping trusted`.' },
  { id: 'd3-f016', topic: '3.2', front: '`dhcp-snoop-client-req drop-untrusted` (default) means…?', back: 'The switch broadcasts DHCP client requests only out trusted ports in the VLAN.' },
  { id: 'd3-f017', topic: '3.2', front: 'DHCP server access list limits?', back: 'FortiOS 7.0.1+, disabled by default. 255 servers per table, 2,048 in total.' },
  { id: 'd3-f018', topic: '3.2', front: 'Option-82 formats?', back: '`ascii` (default, selectable circuit-ID/remote-ID fields) or `legacy` (fixed). Needs FortiOS 7.4.0 + FortiSwitchOS 7.2.2.' },
  { id: 'd3-f019', topic: '3.2', front: 'DHCP-snooping static entry rules?', back: 'Untrusted, non-802.1X port; snooping-enabled VLAN; one MAC ↔ one IPv4; max **64** per switch. Needed for DAI with static-IP hosts.' },
  { id: 'd3-f020', topic: '3.2', front: 'DAI prerequisites and default?', back: 'DHCP snooping must be enabled first. DAI is off on all VLANs by default; enable per VLAN with `switch-controller-arp-inspection`.' },
  { id: 'd3-f021', topic: '3.2', front: 'ARP monitor mode (FortiOS 7.4.4+)?', back: 'VLAN: `switch-controller-arp-inspection monitor`. DHCP-trusted port: `set allow-arp-monitor enable`. Bindings go to the snooping database.' },
  { id: 'd3-f022', topic: '3.2', front: 'IPv4 source guard essentials?', back: 'Per port, off by default; static `binding-entry` + snooping entries; static beats dynamic; drops not logged; >2,048 entries errors.' },
  { id: 'd3-f023', topic: '3.2', front: 'Storm control defaults?', back: 'Rate 500 pps; broadcast, unknown-unicast and unknown-multicast all disabled. Per-port policy needs `storm-control-mode override`.' },
  { id: 'd3-f024', topic: '3.3', front: 'FortiLink-mode ACL facts?', back: 'FortiOS/FortiSwitchOS 7.4.0+, ingress only, classifier + drop/count, `acl group`, port `acl-group`, ACL group 3, `switch-info acl-counters`.' },
  { id: 'd3-f025', topic: '3.3', front: 'Block intra-VLAN traffic: keyword and limits?', back: '`set switch-controller-access-vlan enable`. Not with hardware/software-switch FortiLink; no client IPv6. Exceptions via proxy ARP + same-interface policy.' },
  { id: 'd3-f026', topic: '3.3', front: 'Quarantine modes?', back: '`by-vlan` (default since 6.4.1, quarantine VLAN) or `by-redirect` (`QuarantinedDevices` address group). `config user quarantine`; 512 entries.' },
  { id: 'd3-f027', topic: '3.3', front: 'Secure fabric `auto-isl-auth` values?', back: '`legacy` (default, none), `relax` (restricted trunk on failure), `strict` (no trunk on failure). FortiOS/FortiSwitchOS 7.4.1+.' },
  { id: 'd3-f028', topic: '3.3', front: 'Does FortiGate inspection see intra-VLAN switch traffic?', back: 'No — it\'s switched locally. Only routed (inter-VLAN) or deliberately hairpinned traffic hits firewall policies and security profiles.' },
];
